def clean(df):
    df = df.copy()
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # normalize text labels (strip whitespace / case variants)
    for c in ['Product', 'Category', 'Region']:
        if c in df.columns:
            df[c] = df[c].astype('string').str.strip().str.replace(r'\s+', ' ', regex=True)
            df[c] = df[c].replace({'': pd.NA})
    # canonical category labels
    if 'Category' in df.columns:
        canon = {'electronics': 'Electronics', 'accessories': 'Accessories',
                 'furniture': 'Furniture', 'office supplies': 'Office Supplies'}
        df['Category'] = df['Category'].map(lambda v: canon.get(str(v).lower(), v) if pd.notna(v) else v)
    # parse numbers stored as text (e.g. '$180.00')
    for c in ['Quantity', 'Price', 'Revenue', 'Order_ID']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c].astype(str).str.replace(r'[$,]', '', regex=True).str.strip(), errors='coerce')
    # fix invalid dates
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce').dt.strftime('%Y-%m-%d')
    # drop rows with missing group key (Region)
    df = df[df['Region'].notna()]
    return df.reset_index(drop=True)

def answer(df):
    d = clean(df)
    g = d.groupby('Region')['Quantity'].sum()
    return {str(k): int(v) for k, v in g.items()}
